// Ref: #/components/schemas/state
type State string

const (
	StateInbox       State = "inbox"
	StateHorizon     State = "horizon"
	StateResearching State = "researching"
	StateBuilding    State = "building"
	StateEvaluating  State = "evaluating"
)

// AllValues returns all State values.
func (State) AllValues() []State {
	return []State{
		StateInbox,
		StateHorizon,
		StateResearching,
		StateBuilding,
		StateEvaluating,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s State) MarshalText() ([]byte, error) {
	switch s {
	case StateInbox:
		return []byte(s), nil
	case StateHorizon:
		return []byte(s), nil
	case StateResearching:
		return []byte(s), nil
	case StateBuilding:
		return []byte(s), nil
	case StateEvaluating:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *State) UnmarshalText(data []byte) error {
	switch State(data) {
	case StateInbox:
		*s = StateInbox
		return nil
	case StateHorizon:
		*s = StateHorizon
		return nil
	case StateResearching:
		*s = StateResearching
		return nil
	case StateBuilding:
		*s = StateBuilding
		return nil
	case StateEvaluating:
		*s = StateEvaluating
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

